package com.qualiscan.security;
import com.qualiscan.repo.*; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.security.MessageDigest; import java.util.*;
import org.springframework.context.annotation.*; import org.springframework.http.HttpMethod; import org.springframework.security.authentication.*; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.core.userdetails.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.stereotype.Component; import org.springframework.web.cors.*; import org.springframework.web.filter.OncePerRequestFilter;
@Configuration @EnableMethodSecurity
public class SecurityConfig {
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean UserDetailsService userDetailsService(AppUserRepository users){return username->users.findByUsername(username).map(u->User.withUsername(u.getUsername()).password(u.getPasswordHash()).roles(u.getRole().name()).disabled(!u.isEnabled()).build()).orElseThrow(()->new UsernameNotFoundException("User not found"));}
 @Bean SecurityFilterChain filterChain(HttpSecurity http,JwtFilter jwt,DeviceFilter device)throws Exception{return http.csrf(c->c.disable()).cors(c->{}).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/login").permitAll().requestMatchers(HttpMethod.POST,"/api/inspections").hasRole("DEVICE").requestMatchers(HttpMethod.GET,"/api/profiles","/api/profiles/*").hasAnyRole("DEVICE","ADMIN","SUPERVISOR","OPERATOR").requestMatchers("/api/admin/**").hasRole("ADMIN").requestMatchers("/api/lines/**").hasAnyRole("ADMIN","SUPERVISOR","OPERATOR").requestMatchers("/api/**").authenticated().anyRequest().permitAll()).exceptionHandling(e->e.authenticationEntryPoint((req,res,ex)->SecurityErrors.write(res,401,"Unauthorized",req.getRequestURI())).accessDeniedHandler((req,res,ex)->SecurityErrors.write(res,403,"Forbidden",req.getRequestURI()))).addFilterBefore(device,UsernamePasswordAuthenticationFilter.class).addFilterAfter(jwt,DeviceFilter.class).build();}
 @Bean CorsConfigurationSource corsConfigurationSource(){CorsConfiguration c=new CorsConfiguration();c.setAllowedOrigins(List.of("http://localhost:5173","http://localhost:3000"));c.setAllowedMethods(List.of("GET","POST","PUT","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("*"));c.setAllowCredentials(true);UrlBasedCorsConfigurationSource s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;}
}
@Component class DeviceFilter extends OncePerRequestFilter {
 private final ProductionLineRepository lines; DeviceFilter(ProductionLineRepository lines){this.lines=lines;}
 @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException {String key=req.getHeader("X-API-Key");if(key!=null){boolean allowed=req.getMethod().equals("POST")&&req.getRequestURI().equals("/api/inspections")||req.getMethod().equals("GET")&&(req.getRequestURI().equals("/api/profiles")||req.getRequestURI().startsWith("/api/profiles/"));if(!allowed){SecurityErrors.write(res,403,"Device key cannot access this endpoint",req.getRequestURI());return;}byte[] candidate=HexFormat.of().parseHex(Crypto.sha256(key));var line=lines.findAll().stream().filter(l->MessageDigest.isEqual(candidate,HexFormat.of().parseHex(l.getApiKeyHash()))).findFirst();if(line.isEmpty()){SecurityErrors.write(res,401,"Invalid device key",req.getRequestURI());return;}UsernamePasswordAuthenticationToken auth=new UsernamePasswordAuthenticationToken("device:"+line.get().getId(),null,List.of(new SimpleGrantedAuthority("ROLE_DEVICE")));auth.setDetails(line.get());SecurityContextHolder.getContext().setAuthentication(auth);}chain.doFilter(req,res);}
}
@Component class JwtFilter extends OncePerRequestFilter {
 private final JwtService jwt; JwtFilter(JwtService jwt){this.jwt=jwt;}
 @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException {String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")&&SecurityContextHolder.getContext().getAuthentication()==null){try{var claims=jwt.parse(h.substring(7)).getPayload();String user=claims.getSubject(),role=claims.get("role",String.class);var auth=new UsernamePasswordAuthenticationToken(user,null,List.of(new SimpleGrantedAuthority("ROLE_"+role)));SecurityContextHolder.getContext().setAuthentication(auth);}catch(RuntimeException ex){SecurityErrors.write(res,401,"Invalid or expired token",req.getRequestURI());return;}}chain.doFilter(req,res);}
}
final class SecurityErrors {private SecurityErrors(){} static void write(HttpServletResponse response,int status,String message,String path)throws IOException{response.setStatus(status);response.setContentType("application/json");response.setCharacterEncoding("UTF-8");response.getWriter().write("{\"timestamp\":\""+java.time.Instant.now()+"\",\"status\":"+status+",\"error\":\""+(status==401?"Unauthorized":"Forbidden")+"\",\"message\":\""+message.replace("\\","\\\\").replace("\"","\\\"")+"\",\"path\":\""+path.replace("\\","\\\\").replace("\"","\\\"")+"\"}");}}
